import ctypes, time; mci = ctypes.windll.winmm.mciSendStringW; print('open', mci('open "Hymn RP 1 zwrotka.mp3" type mpegvideo alias anthem', None, 0, 0)); print('play', mci('play anthem from 0', None, 0, 0)); time.sleep(2); print('pause', mci('pause anthem', None, 0, 0)); time.sleep(2); print('resume', mci('resume anthem', None, 0, 0)); time.sleep(2); print('vol0', mci('setaudio anthem volume to 0', None, 0, 0)); time.sleep(2); print('vol200', mci('setaudio anthem volume to 200', None, 0, 0)); time.sleep(2)
